<span class="line"><span style="--shiki-dark:#C586C0;--shiki-light:#AF00DB;">    return</span><span style="--shiki-dark:#9CDCFE;--shiki-light:#001080;"> ips</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">, </span><span style="--shiki-dark:#9CDCFE;--shiki-light:#001080;">ttl</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">, </span><span style="--shiki-dark:#9CDCFE;--shiki-light:#001080;">err</span></span>
